-- Instrument capability guard, appended after src/endoscope/rcm_controller.lua in
-- scenes/davinci_si_instruments.ttt. INSTRUMENTS is generated by scripts/build/install_instruments.py from the
-- instrument IDENTIFIED from scene geometry (scripts/build/instrument_guard.py), never from a role label:
--   INSTRUMENTS[arm] = {model=..., name=..., capabilities={...}}
-- A kinematic grasp needs the 'grasp' capability, so the scissors cannot hold an object.
local function hasCapability(arm,capability)
    local entry=INSTRUMENTS and INSTRUMENTS[arm.arm]
    if not entry then return false end
    for _,c in ipairs(entry.capabilities) do if c==capability then return true end end
    return false
end
-- Jaw kinematics with a moving hinge (ProGrasp): the hinge slide follows the jaw opening (both jaw joints =
-- angle, jaw = 2*angle) with the dvrk_model law, clamped to the range in which that law was measured.
local baseSetGrip=setGrip
function setGrip(index,angle)
    local arm=arms[index]
    local entry=arm and INSTRUMENTS and INSTRUMENTS[arm.arm]
    if not entry or not entry.hinge_slide then return baseSetGrip(index,angle) end
    -- The base controller validates too, but the slide must not move (or do arithmetic on bad input)
    -- before that validation. Intervals here are the installed per-joint bounds, not the total jaw range.
    if type(angle)~='number' or angle~=angle or math.abs(angle)==math.huge or not arm.grip or #arm.grip==0 then return false end
    for _,h in ipairs(arm.grip) do
        local cyclic,lim=sim.getJointInterval(h)
        if not cyclic and (not lim or angle<lim[1] or angle>lim[1]+lim[2]) then return false end
    end
    if not entry.slideHandle then
        for _,h in ipairs(sim.getObjectsInTree(sim.handle_scene,sim.handle_all,0)) do
            if sim.getObjectAlias(h)==entry.hinge_slide then entry.slideHandle=h end
        end
    end
    local slide=entry.slideHandle
    local old=sim.getJointPosition(slide)
    local jaw=math.min(math.max(2*angle,entry.hinge_jaw_range_rad[1]),entry.hinge_jaw_range_rad[2])
    sim.setJointPosition(slide,entry.hinge_slope_m_per_rad*jaw)
    local ok=baseSetGrip(index,angle)
    if not ok then sim.setJointPosition(slide,old) end
    return ok
end
local baseGrasp=grasp
function grasp(index,alias)
    local arm=arms[index]
    if not arm or not hasCapability(arm,'grasp') then
        if arm then arm.capabilityRefusals=(arm.capabilityRefusals or 0)+1 end
        return false
    end
    return baseGrasp(index,alias)
end
function getInstrument(index)
    local arm=arms[index]
    if not arm then return nil end
    local entry=INSTRUMENTS[arm.arm]
    return {arm=arm.arm,model=entry and entry.model or '',capabilities=entry and entry.capabilities or {},
            capability_refusals=arm.capabilityRefusals or 0}
end
function hasInstrumentCapability(index,capability)
    local arm=arms[index]
    return arm~=nil and hasCapability(arm,capability)
end
